436	// createMirrors fans out CreateMirror (and the clone-readiness poll) across all
437	// targets in parallel, returning one result per target in input order. One
438	// cluster client is built per region and shared across that region's repos; a
439	// region the active login can't reach fails every pair in that region rather
440	// than aborting the whole run.
441	func createMirrors(ctx context.Context, errW io.Writer, targets []mirrorTarget, noWait bool, waitTimeout time.Duration) []mirrorResult {
442		// One client per distinct region, built once.
443		clientByHost := make(map[string]*coreapi.Client)
444		clientErrByHost := make(map[string]error)
445		for _, t := range targets {
446			if _, seen := clientByHost[t.region.host]; seen {
447				continue
448			}
449			if _, seen := clientErrByHost[t.region.host]; seen {
450				continue
451			}
452			c, err := coreapi.NewForCluster(ctx, t.region.host)
453			if err != nil {
454				clientErrByHost[t.region.host] = err
455			} else {
456				clientByHost[t.region.host] = c
457			}
458		}
459	
460		// Docker-pull-style live progress: one line per (repo, region), each
461		// updating independently as its CreateMirror + clone poll advance.
462		labels := make([]string, len(targets))
463		for i, t := range targets {
464			labels[i] = t.owner + "/" + t.repo + " @ " + t.region.host
465		}
466		prog := newMirrorProgress(errW, labels)
467		prog.start()
468	
469		results := make([]mirrorResult, len(targets))
470		g := new(errgroup.Group)
471		g.SetLimit(mirrorCreateConcurrency)
472		for i, t := range targets {
473			g.Go(func() error {
474				results[i] = createOneMirror(ctx, t, clientByHost[t.region.host], clientErrByHost[t.region.host], noWait, waitTimeout,
475					func(status string, final, ok bool) { prog.set(i, status, final, ok) })
476				return nil
477			})
478		}
479		// createOneMirror folds every failure into results and never returns an
480		// error, so Wait is structurally always nil; check it anyway to satisfy
481		// errcheck and stay correct if that invariant ever changes.
482		if err := g.Wait(); err != nil {
483			fmt.Fprintf(errW, "mirror creation: %v\n", err)
484		}
485		prog.stop()
486		return results
487	}
488	
489	// createOneMirror registers a single (repo, region) mirror and, unless noWait
490	// or the upstream is empty, waits for its initial clone. It never returns an
491	// error: every outcome is folded into the mirrorResult so a single failure
492	// can't sink the batch. report (may be nil) is called as the mirror moves
493	// through its phases so the caller can render live progress; the final call has
494	// final=true and ok set to whether it succeeded.
495	func createOneMirror(ctx context.Context, t mirrorTarget, c *coreapi.Client, clientErr error, noWait bool, waitTimeout time.Duration, report func(status string, final, ok bool)) mirrorResult {
496		if report == nil {
497			report = func(string, bool, bool) {}
498		}
499		res := mirrorResult{owner: t.owner, repo: t.repo, regionLabel: regionLabel(t.region)}
500		if clientErr != nil {
501			res.status, res.err = mirrorStatusError, clientErr
502			report(mirrorStatusError, true, false)
503			return res
504		}
505		report("creating", false, false)
506		// Same create-then-wait path as the one-shot `repo mirror create <url>`
507		// (createAndAwaitMirror), so both report identical lifecycle states. The
508		// per-poll status drives this mirror's progress line.
509		outcome, err := createAndAwaitMirror(ctx, c, t.owner, t.repo, t.region.host, noWait, waitTimeout, nil,
510			func(s coreapi.MirrorStatus) { report(string(s), false, false) })
511		if outcome.created == nil {
512			res.status, res.err = mirrorStatusError, renderCoreError(err)
513			report(mirrorStatusError, true, false)
514			return res
515		}
516		res.cloneURL = outcome.created.MirrorUrl
517	
518		if outcome.created.Suspended {
519			// An admin suspended this existing placement, so it won't be served.
520			// Surface it as a distinct status and set an error so the batch exits
521			// non-zero, matching the one-shot: a suspended mirror isn't a success.
522			res.status, res.err = mirrorStatusSuspended, errors.New("suspended by an admin; won't be usable")
523			report(mirrorStatusSuspended, true, false)
524			return res
525		}
526	
527		if !outcome.polled {
528			if outcome.created.Empty {
529				res.status = mirrorStatusEmpty
530			} else {
531				res.status = mirrorStatusRegistered
532			}
533			report(res.status, true, true)
534			return res
535		}
536	
537		// nonTerminal classifies a still-processing/unknown result: the poll ended
538		// without a terminal status, so the wait timed out or a poll call errored.
539		nonTerminal := func() {
540			if errors.Is(err, context.DeadlineExceeded) {
541				res.status, res.err = mirrorStatusTimedOut, err
542			} else {
543				res.status, res.err = mirrorStatusError, err
544			}
545		}
546		switch outcome.status {
547		case coreapi.MirrorStatusReady:
548			res.status = mirrorStatusReady
549		case coreapi.MirrorStatusSuspended:
550			res.status, res.err = mirrorStatusSuspended, errors.New("the mirror is suspended; contact support")
551		case coreapi.MirrorStatusFailed:
552			res.status, res.err = mirrorStatusFailed, errors.New("the initial clone failed; contact support")
553		case coreapi.MirrorStatusProcessing:
554			nonTerminal()
555		default:
556			nonTerminal()
557		}
558		report(res.status, true, res.err == nil)
559		return res
560	}
561	
562	// mirrorProgress renders a Docker-pull-style live list: one line per mirror,
563	// each showing its label and a status that updates independently — a spinner
564	// while in flight, ✓/✗ once terminal. On a non-terminal writer (pipes, tests)
565	// it degrades to one printed line per mirror as each reaches a terminal state.
566	type mirrorProgress struct {
567		w       io.Writer
568		tty     bool
569		labelW  int
570		mu      sync.Mutex
571		lines   []mirrorProgressLine
572		frame   int
573		painted bool
574		done    chan struct{}
575		stopped chan struct{}
576	}
577	
578	type mirrorProgressLine struct {
579		label   string
580		status  string
581		final   bool
582		ok      bool
583		printed bool // non-tty: terminal line already emitted
584	}
585	
586	func newMirrorProgress(w io.Writer, labels []string) *mirrorProgress {
587		lines := make([]mirrorProgressLine, len(labels))
588		labelW := 0
589		for i, l := range labels {
590			lines[i] = mirrorProgressLine{label: l, status: "queued"}
591			if n := len(l); n > labelW {
592				labelW = n
593			}
594		}
595		return &mirrorProgress{w: w, tty: interactive.IsTerminalWriter(w), labelW: labelW, lines: lines}
596	}
597	
598	// start paints the initial block and, on a TTY, begins animating the spinner.
599	func (p *mirrorProgress) start() {
600		if !p.tty {
601			return
602		}
603		p.done = make(chan struct{})
604		p.stopped = make(chan struct{})
605		p.mu.Lock()
606		p.renderLocked()
607		p.mu.Unlock()
608		go func() {
609			defer close(p.stopped)
610			ticker := time.NewTicker(spinnerInterval)
611			defer ticker.Stop()
612			for {
613				select {
614				case <-p.done:
615					return
616				case <-ticker.C:
617					p.mu.Lock()
618					p.frame++
619					p.renderLocked()
620					p.mu.Unlock()
621				}
622			}
623		}()
624	}
625	
626	// set updates one mirror's line. On a TTY it repaints immediately; otherwise it
627	// prints a single line the first time the mirror reaches a terminal state.
628	func (p *mirrorProgress) set(i int, status string, final, ok bool) {
629		p.mu.Lock()
630		defer p.mu.Unlock()
631		p.lines[i].status = status
632		p.lines[i].final = final
633		p.lines[i].ok = ok
634		switch {
635		case p.tty:
636			p.renderLocked()
637		case final && !p.lines[i].printed:
638			p.lines[i].printed = true
639			fmt.Fprintf(p.w, "%s %s %s\n", terminalIcon(ok), p.lines[i].label, status)
640		}
641	}
642	
643	// stop ends the animation and leaves the final state painted.
644	func (p *mirrorProgress) stop() {
645		if !p.tty {
646			return
647		}
648		close(p.done)
649		<-p.stopped
650		p.mu.Lock()
651		p.renderLocked()
652		p.mu.Unlock()
653	}
654	
655	// renderLocked repaints the whole block in place. Caller holds p.mu.
656	func (p *mirrorProgress) renderLocked() {
657		if p.painted {
658			fmt.Fprintf(p.w, "\033[%dA", len(p.lines)) // move up to the block's top
659		}
660		p.painted = true
661		for _, ln := range p.lines {
662			var icon string
663			if ln.final {
664				icon = terminalIcon(ln.ok)
665			} else {
666				icon = spinnerFrames[p.frame%len(spinnerFrames)]
667			}
668			fmt.Fprintf(p.w, "\r\033[K%-*s  %s %s\n", p.labelW, ln.label, icon, ln.status)
669		}
670	}
671	
672	func terminalIcon(ok bool) string {
673		if ok {
674			return "✓"
675		}
676		return "✗"
677	}
678	
679	// reportMirrorResults renders the results table, a copy-pasteable git-clone
680	// block for the ready mirrors, and per-failure detail. It returns a
681	// SilentError (so the table isn't reprinted) when any mirror failed, giving the
682	// command a non-zero exit while still showing what succeeded.
683	func reportMirrorResults(outW, errW io.Writer, results []mirrorResult) error {
684		if len(results) == 0 {
685			return nil
686		}
687		// Headroom between the live progress block and the summary table.
688		fmt.Fprintln(outW)
689		if err := printTable(outW, mirrorCreateResultColumns, results, mirrorCreateResultRow); err != nil {
690			return err
691		}
692	
693		var readyURLs []string
694		var failures int
695		for _, r := range results {
696			if r.status == mirrorStatusReady && r.cloneURL != "" {
697				readyURLs = append(readyURLs, r.cloneURL)
698			}
699			if r.err != nil {
700				failures++
701			}
702		}
703		if len(readyURLs) > 0 {
704			fmt.Fprintln(outW, "\nClone them:")
705			for _, u := range readyURLs {
706				fmt.Fprintf(outW, "  git clone %s\n", u)
707			}
708		}
709		if failures > 0 {
710			for _, r := range results {
711				if r.err != nil {
712					fmt.Fprintf(errW, "%s/%s @ %s: %v\n", r.owner, r.repo, r.regionLabel, r.err)
713				}
714			}
715			return NewSilentError(fmt.Errorf("%d mirror(s) failed", failures))
716		}
717		return nil
718	}
719

